#!/usr/bin/env bash
# PersonaForge 1-command cloud trainer - @@TRIGGER@@ (generated by prepare_dataset.py --cloud)
#
#   bash run_cloud_training.sh            # SDXL LoRA, then Flux LoRA
#
# Options (environment variables):
#   FLUX_TIER=auto|80gb|48gb|24gb   ai-toolkit config to use (auto = from the GPU's memory)
#   SKIP_SDXL=1 / SKIP_FLUX=1       train only one of the two
#   WORKSPACE=/workspace            where vultr_cloud_setup.sh installed everything
#   COMFY_URL=http://127.0.0.1:8188 the cloud ComfyUI whose VRAM is released first
#
# Steps:
#   1. POST /free to ComfyUI so it unloads every model and releases VRAM before training
#   2. SDXL LoRA (kohya sd-scripts), then Flux LoRA (ai-toolkit), one after the other
#   3. copy the finished .safetensors into $WORKSPACE/ComfyUI/models/loras/ AND $WORKSPACE/finished_loras/,
#      then print the scp command that copies them to your Windows PC
set -euo pipefail

BUNDLE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
WORKSPACE="${WORKSPACE:-/workspace}"
COMFY_URL="${COMFY_URL:-http://127.0.0.1:8188}"
FLUX_TIER="${FLUX_TIER:-auto}"
SKIP_SDXL="${SKIP_SDXL:-0}"
SKIP_FLUX="${SKIP_FLUX:-0}"
TRIGGER="@@TRIGGER@@"
GENERATED_ROOT="@@ROOT@@"
COMFY_LORAS="$WORKSPACE/ComfyUI/models/loras"
FINISHED="$WORKSPACE/finished_loras"
OUTPUT="$BUNDLE/output"

say() { printf '\n\033[1;36m>> %s\033[0m\n' "$*"; }
die() { printf '\033[1;31m!! %s\033[0m\n' "$*" >&2; exit 1; }

# The configs carry absolute paths for the folder the bundle was generated for; follow the bundle if it was
# unzipped somewhere else.
if [ "$BUNDLE" != "$GENERATED_ROOT" ]; then
  say "Bundle is at $BUNDLE (configs were written for $GENERATED_ROOT): updating the paths"
  grep -rlF "$GENERATED_ROOT" "$BUNDLE/cloud" | xargs -r sed -i "s#$GENERATED_ROOT#$BUNDLE#g"
fi

# ------------------------------------------------------------------------------------------- pre-flight
SDXL_VENV="$WORKSPACE/sd-scripts/venv"
AIT_DIR="$WORKSPACE/ai-toolkit"
if [ "$SKIP_SDXL" != "1" ]; then
  [ -f "$SDXL_VENV/bin/activate" ] || die "kohya sd-scripts not found in $WORKSPACE/sd-scripts: run vultr_cloud_setup.sh first"
  [ -f "$BUNDLE/cloud/kohya_sdxl_train.sh" ] || die "missing $BUNDLE/cloud/kohya_sdxl_train.sh"
fi
if [ "$SKIP_FLUX" != "1" ]; then
  [ -f "$AIT_DIR/venv/bin/activate" ] || die "ai-toolkit not found in $AIT_DIR: run vultr_cloud_setup.sh first"
  if [ -z "${HF_TOKEN:-}" ] && [ ! -s "$HOME/.cache/huggingface/token" ]; then
    die "FLUX.1-dev is gated: accept its licence on Hugging Face, then  export HF_TOKEN=hf_xxx  and re-run (or SKIP_FLUX=1)"
  fi
  if [ "$FLUX_TIER" = "auto" ]; then
    MIB="$(nvidia-smi --query-gpu=memory.total --format=csv,noheader,nounits | head -1 | tr -d ' ')"
    if [ "${MIB:-0}" -ge 70000 ]; then FLUX_TIER=80gb; elif [ "${MIB:-0}" -ge 40000 ]; then FLUX_TIER=48gb; else FLUX_TIER=24gb; fi
    echo "GPU memory ${MIB} MiB -> Flux config $FLUX_TIER"
  fi
  FLUX_YAML="$BUNDLE/cloud/ai-toolkit_flux_${FLUX_TIER}.yaml"
  [ -f "$FLUX_YAML" ] || die "missing $FLUX_YAML (FLUX_TIER must be 80gb, 48gb or 24gb)"
fi
mkdir -p "$OUTPUT" "$COMFY_LORAS" "$FINISHED"

# ------------------------------------------------------------------------------------------- 1. free VRAM
say "Asking ComfyUI ($COMFY_URL) to unload all models and free VRAM"
if curl -fsS -X POST "$COMFY_URL/free" -H 'Content-Type: application/json' -d '{"unload_models":true,"free_memory":true}' >/dev/null 2>&1; then
  sleep 3
  echo "ComfyUI released its models."
else
  echo "ComfyUI is not answering at $COMFY_URL (not running?) - nothing to free."
fi
nvidia-smi --query-gpu=name,memory.used,memory.total --format=csv,noheader || true

START=$(date +%s)
# ------------------------------------------------------------------------------------------- 2a. SDXL
if [ "$SKIP_SDXL" != "1" ]; then
  say "SDXL LoRA (kohya sd-scripts, rank 32, 2000 steps, a checkpoint every 250)"
  (
    # shellcheck disable=SC1091
    source "$SDXL_VENV/bin/activate"
    bash "$BUNDLE/cloud/kohya_sdxl_train.sh" "$WORKSPACE/sd-scripts"
  )
  echo "SDXL done after $(( ($(date +%s) - START) / 60 )) min"
fi

# ------------------------------------------------------------------------------------------- 2b. Flux
if [ "$SKIP_FLUX" != "1" ]; then
  say "Flux LoRA (ai-toolkit, $FLUX_TIER config)"
  (
    cd "$AIT_DIR"
    # shellcheck disable=SC1091
    source venv/bin/activate
    python run.py "$FLUX_YAML"
  )
  echo "Flux done after $(( ($(date +%s) - START) / 60 )) min in total"
fi

# ------------------------------------------------------------------------------------------- 3. collect
say "Copying the finished LoRAs"
mapfile -t ALL < <(find "$OUTPUT" -type f -name '*.safetensors' | sort)
[ "${#ALL[@]}" -gt 0 ] || die "no .safetensors files in $OUTPUT - check the training log above"
FINALS=()
for f in "${ALL[@]}"; do
  name="$(basename "$f")"
  case "$name" in
    "${TRIGGER}_sdxl_lora.safetensors"|"${TRIGGER}_flux_lora.safetensors") FINALS+=("$f") ;;
  esac
done
[ "${#FINALS[@]}" -gt 0 ] || FINALS=("${ALL[@]}")
mkdir -p "$FINISHED/checkpoints"
for f in "${FINALS[@]}"; do
  cp -f "$f" "$COMFY_LORAS/"
  cp -f "$f" "$FINISHED/"
  echo "  $(basename "$f")  ->  $COMFY_LORAS/  and  $FINISHED/"
done
# Intermediate step checkpoints (every 250 steps): pick an earlier one if the final looks over-trained.
for f in "${ALL[@]}"; do
  printf '%s\n' "${FINALS[@]}" | grep -qxF "$f" || cp -f "$f" "$FINISHED/checkpoints/"
done
echo "  step checkpoints -> $FINISHED/checkpoints/ ($(find "$FINISHED/checkpoints" -name '*.safetensors' | wc -l) files)"
curl -fsS "$COMFY_URL/object_info/LoraLoader" >/dev/null 2>&1 && echo "The cloud ComfyUI sees the new LoRAs (press Refresh Models in the studio)." || true

IP="$(curl -fsS --max-time 5 https://api.ipify.org 2>/dev/null || hostname -I | awk '{print $1}')"
USER_NAME="$(id -un)"
say "Done. Copy the LoRAs to your Windows laptop - run this in PowerShell ON THE LAPTOP:"
cat <<EOF

  scp "${USER_NAME}@${IP}:${FINISHED}/*.safetensors" "@@LOCAL_LORAS@@"

  (step checkpoints too, into loras\checkpoints:  scp -r "${USER_NAME}@${IP}:${FINISHED}/checkpoints" "@@LOCAL_LORAS@@")

Then press "Refresh Models" in the studio and set the LoRA on the character
(SDXL LoRA field: ${TRIGGER}_sdxl_lora.safetensors, Flux LoRA field: ${TRIGGER}_flux_lora.safetensors).
Remember to STOP or DESTROY the Vultr instance when you are done - it bills by the hour.
EOF
